#include "scamptrie_dynamic.h"

uint32_t ScampTrieDynamic::insert_prefix(ip6_t prefix, uint8_t len, nexthop_t nh) {
    if (len > 128) return SCAMPTRIE_FAIL;
    if (nh > 4194302ULL) return SCAMPTRIE_FAIL;
    if (fib_.size() >= static_cast<size_t>(MAX_FIB_ENTRIES) &&
        fib_.find(prefix, len) < 0)
        return SCAMPTRIE_FAIL; // would exceed the documented FIB bound
    fib_.insert(prefix, len, static_cast<uint32_t>(nh));
    return SCAMPTRIE_OK;
}

nexthop_t ScampTrieDynamic::lookup(ip6_t ip) const {
    int32_t h = fib_.longest_match(ip, 128);
    if (h < 0) return LPM_INVALID_NH;
    return static_cast<nexthop_t>(h);
}
